.equipment-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 12px;
  width: 100%;
}
.equipment-card {
  min-width: 0;
  padding: 12px;
  border: 1px solid #b9cadb;
  border-radius: 8px;
  background: #edf4fc;
}
.equipment-card h2 { margin: 0; font-size: 1.125rem; }
.equipment-card p { margin: 4px 0 0; }

@media (min-width: 680px) {
  .equipment-grid { grid-template-columns: 50% 50%; }
}

