.scanner-lane {
  position: relative;
  width: 228px;
  max-width: 100%;
  padding: 8px;
  border-radius: 6px;
  background: #e9f1f8;
}
.scan-target {
  position: absolute;
  top: 8px;
  left: 88px;
  width: 60px;
  height: 38px;
  outline: 2px dashed #6285a5;
  border-radius: 6px;
}
.scanner-head {
  width: 60px;
  height: 38px;
  line-height: 38px;
  text-align: center;
  border-radius: 6px;
  background: #2a5379;
  color: white;
}

.scanner-head { transform: translateY(80px); }

