.stamp-stage {
  width: 220px;
  max-width: 100%;
  margin-top: 12px;
  padding: 30px 12px 12px;
  border: 1px solid #dfcba9;
  border-radius: 8px;
  background: #fff8e9;
}
.stamp-slot { display: inline-block; outline: 1px dashed #8f6f37; border-radius: 5px; }
.dispatch-stamp {
  display: block;
  padding: 4px 10px;
  border-radius: 5px;
  background: #846031;
  color: white;
  opacity: 0.55;
  transform: translateY(-8px);
}
.stamp-stage .dispatch-stamp { animation-play-state: paused; }

@keyframes settle-stamp {
  from { opacity: 0.3; transform: translateY(-18px); }
  to { opacity: 1; transform: translateY(0); }
}
.dispatch-stamp { animation: settle-stamp 400ms ease-out; }
